SET time_zone='+00:00',lock_wait_timeout=5,innodb_lock_wait_timeout=5,MAX_EXECUTION_TIME=5000;
SELECT c.id,c.state,c.decided_at,c.task_id,c.base_revision,m.revision,t.state task_state,t.last_error,t.output_kind,t.output_id,e.id execution_id,e.state execution_state,e.execution_no,e.task_attempt,e.finished_at,e.request_hash execution_request_hash,o.id operation_id,o.state operation_state,o.current_execution_no,o.request_hash logical_request_hash,o.external_result_id,a.outcome,a.ended_at FROM generation_candidate c JOIN meeting m ON m.id=c.meeting_id JOIN durable_task t ON t.id=c.task_id JOIN external_execution e ON e.task_id=t.id JOIN external_operation o ON o.id=e.operation_id JOIN task_attempt a ON a.task_id=t.id AND a.attempt=e.task_attempt WHERE t.id='984bb6d0-78de-411d-bba6-4a052411dc97';
